### 思路

准备贴一张 $2\times2$ 贴纸时，前三个目标格为空而第四格已被占用，这次操作应完全失败。如果边检查边把前三格写成新编号，就会留下半张不存在的贴纸；因此贴入必须先检查整个区域，再统一修改。

#### 板子与贴纸记录分别存什么

二维 grid 保存每个格子的所属编号，零表示空格，用于重叠检查和单格查询。每次成功贴入后，还在 st 中保存该编号的左上角、高、宽与 alive 状态，用于之后找到整张贴纸并删除。编号按成功贴入顺序增长，删除记录只改状态，不从 st 中移除，因此旧编号不会被重复使用。

#### 贴入、删除如何保持一致

贴入先检查最下行 $x+h-1$ 和最右列 $y+w-1$ 是否仍在板内。越界时立即失败，不能先访问二维数组。完全在板内后才逐格确认全为零；全部通过才分配编号、写入所有格子，并令 covered 增加 $hw$。失败时编号、格子和覆盖计数都保持不变。

删除先确认编号曾经分配过且 alive 为真，再按记录的矩形把格子清零、从 covered 减去面积、标记已删除。因为贴纸从不重叠，且仍存在的贴纸所占格子不能被新贴纸覆盖，清空整个原矩形一定只删除它自己的格子。已删除的编号再请求删除，应直接报 Error。

查询只读取一个合法格子的编号。结束后遍历 st 统计 alive 为真的数量，covered 已在每次成功操作后维护好，可以直接输出。每次贴入或删除最多扫描全板，时间上界 $O(qnm)$，本题板子只有 $50\times50$，足以直接模拟。

### 同一张板上，先整块检查，再真的贴入

![一块3行4列板上的真实失败、删除和再次贴入轨迹](assets/editorial-reasoning/core34-sticker-board.svg)

图中板为3行4列。先在(2,2)贴1×1，成功编号1。随后尝试在(1,1)贴2×2：按行检查时前三格空，第四格(2,2)已是1，所以整张失败，前三格仍是0，新编号也没有消耗。接着贴(1,4)的1×1，得到编号2；删除1后再贴(1,1)的2×2，得到编号3。最后1已删除，2与3仍在，实际盖住1+4=5格。

贴入的四项边界检查先保证整个矩形在板内，才可访问grid。x、y至少一已由输入保证，代码再次检查只是重复确认；高宽为正，所以最下行x+h−1和最右列y+w−1在界内就够了。两个循环确认目标格全为0；遇到一格非零，就足以证明重叠，没必要继续找其他冲突。检查期间不写入，失败分支自然保持整张板、编号表和covered完全不变。

全部通过时，目标格就是完整的空矩形，与现存贴纸不相交；这已经充分保证可以贴上。st最初只含不用的0号占位，每次成功才追加一条记录，因此 `st.size()` 正好是下一个成功编号。图中第二次操作失败，第三次仍取编号2；删除1只改alive，不删记录，后来也不会复用1。

删除条件按从左到右短路：先确认id至少一，再确认id小于st.size()，最后才安全读取st[id].alive。第一项由合法输入已保证，后两项分别排除从未分配和已经取下的编号。尚在的记录所指矩形一直归它所有：新贴纸只能进入空格，不可能覆盖这些格子，因此无需逐格再核对所有权，清空记录里的整块区域就只删除这一张。alive随后置假，第二次删除同一id会失败，不能再减面积。

每次成功贴入增加hw，每次成功删除减少同一hw；现存矩形互不重叠，所以covered始终恰为真实非零格数量。最后 `alive_cnt++` 是对一条仍在场的成功记录加一，每张有唯一且保留的编号，故不重不漏；曾经成功但后来删除的记录不会计入。查询位置由输入保证在板内，直接读grid即可。面积最大nm不超过2500，编号最大成功次数不超过q，原程序的int足够。

### 参考代码

```cpp
#include <iostream>
#include <vector>
using namespace std;

struct Sticker {                    // 一张成功贴上过的贴纸
    int x, y;                       // 左上角位置（1 下标）
    int h, w;                       // 占用的行数、列数
    bool alive;                     // 现在还在不在贴纸板上
};

int main() {
    int n, m, q;
    cin >> n >> m >> q;             // n 行 m 列的板子，q 个操作
    // grid[i][j] = 盖住这一格的贴纸编号，0 表示空格（行列都从 1 开始，多开一圈防越界）
    vector<vector<int>> grid(n + 1, vector<int>(m + 1, 0));
    vector<Sticker> st(1);          // st[id] = 第 id 号贴纸；st[0] 是占位，不用
    int covered = 0;                // 当前被贴纸盖住的格子总数

    for (int qi = 0; qi < q; qi++) {
        int op;
        cin >> op;

        if (op == 1) {              // 操作 1：试着贴一张新贴纸
            int x, y, h, w;
            cin >> x >> y >> h >> w;
            bool ok = (x >= 1 && y >= 1 && x + h - 1 <= n && y + w - 1 <= m);  // 先看是否完全在板内
            if (ok) {               // 再逐个看目标格子是不是都空着
                for (int i = x; i <= x + h - 1 && ok; i++)
                    for (int j = y; j <= y + w - 1; j++)
                        if (grid[i][j] != 0) { ok = false; break; }
            }
            if (!ok) {
                cout << "Error\n";  // 越界或压到别人：板子一个格子都不改
            } else {
                int id = (int)st.size();        // 新编号 = 之前成功贴上的张数 + 1
                st.push_back({x, y, h, w, true});
                for (int i = x; i <= x + h - 1; i++)
                    for (int j = y; j <= y + w - 1; j++) grid[i][j] = id;   // 逐格登记归属
                covered += h * w;               // 盖住的格子数随之增加
                cout << id << "\n";
            }
        } else if (op == 2) {       // 操作 2：取下一张贴纸
            int id;
            cin >> id;
            if (id >= 1 && id < (int)st.size() && st[id].alive) {   // 贴上过、且现在还贴着
                for (int i = st[id].x; i <= st[id].x + st[id].h - 1; i++)
                    for (int j = st[id].y; j <= st[id].y + st[id].w - 1; j++) grid[i][j] = 0;
                covered -= st[id].h * st[id].w;
                st[id].alive = false;
                cout << "Remove\n";
            } else {
                cout << "Error\n";  // 编号不存在或早就取下了
            }
        } else {                    // 操作 3：查一个格子归谁
            int x, y;
            cin >> x >> y;
            cout << grid[x][y] << "\n";     // 空格输出 0，否则输出贴纸编号
        }
    }

    int alive_cnt = 0;              // 最后统计：还在板上的贴纸张数
    for (size_t i = 1; i < st.size(); i++)
        if (st[i].alive) alive_cnt++;
    cout << alive_cnt << ' ' << covered << "\n";
    return 0;
}
```

### 易错点

成功贴入次数决定新编号，删除后不复用；失败操作不得改变格子或计数。
